import json

grid_rows, grid_cols = 26, 27

test_in = [[8] * grid_cols for _ in range(grid_rows)]
test_in[16][23] = 9
test_in[17][23] = 9
test_in[17][24] = 1
test_in[18][23] = 5
test_in[18][24] = 1

output = [[8] * grid_cols for _ in range(grid_rows)]

cells = defaultdict(list)
for r in range(grid_rows):
    for c in range(grid_cols):
        val = test_in[r][c]
        if val != 8:
            cells[val].append((r, c))

threshold = (grid_rows + grid_cols) / 2  # 26.5

for val, locs in cells.items():
    # Check if cells align on main diagonal (r-c constant) - at least 2 cells share this
    r_minus_c_counts = defaultdict(int)
    for r, c in locs:
        r_minus_c_counts[r - c] += 1

    has_main_diag_alignment = any(count >= 2 for count in r_minus_c_counts.values())

    for r, c in locs:
        if has_main_diag_alignment:
            direction = 'down-right'
        elif r + c < threshold:
            direction = 'up-left'
        else:
            direction = 'down-left'

        dr, dc = 0, 0
        if direction == 'up-left':
            dr, dc = -1, -1
        elif direction == 'down-left':
            dr, dc = 1, -1
        else:
            dr, dc = 1, 1

        output[r][c] = val
        for k in range(1, 20):
            nr, nc = r + dr * k, c + dc * k
            if 0 <= nr < grid_rows and 0 <= nc < grid_cols and output[nr][nc] == 8:
                output[nr][nc] = val
            else:
                break

print("\nOutput cells:")
for r in range(grid_rows):
    row_non_8 = [(r, c, output[r][c]) for c, val in enumerate(output[r]) if val != 8]
